import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CdGZLcRD.js";var i=JSON.parse(`{"title":"Sync vs Async","description":"","frontmatter":{},"headers":[],"relativePath":"guides/the-manual/relational-data/features/sync-vs-async.md","filePath":"guides/the-manual/relational-data/features/sync-vs-async.md"}`),a={name:`guides/the-manual/relational-data/features/sync-vs-async.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="sync-vs-async" tabindex="-1">Sync vs Async <a class="header-anchor" href="#sync-vs-async" aria-label="Permalink to “Sync vs Async”">​</a></h1><p>Every relationship field declares <code>options.async</code>. For <code>resource</code> and <code>collection</code> fields the flag is a <strong>contract about what the API sends</strong>, and WarpDrive enforces it. The precise rules are in the <a href="./../spec#_3-rules-for-resource-and-collection-relationships">Relationship Specification</a>; this page explains them.</p><h2 id="the-rule-that-always-applies" tabindex="-1">The Rule That Always Applies <a class="header-anchor" href="#the-rule-that-always-applies" aria-label="Permalink to “The Rule That Always Applies”">​</a></h2><p>Whatever the value of <code>async</code>, every resource referenced in a <code>resource</code> or <code>collection</code> relationship&#39;s <code>data</code> <strong>must be included</strong> in the payload that references it (in the document&#39;s <code>data</code> or <code>included</code>). The JSON:API validator reports a missing resource as an error, and reading <code>doc.data</code> for a member that was never loaded throws rather than producing an empty record.</p><p>This is the main difference from the legacy <code>belongsTo</code>/<code>hasMany</code> kinds, which tolerate references to resources that are not loaded.</p><h2 id="async-false-sync-the-default" tabindex="-1"><code>async: false</code> (sync, the default) <a class="header-anchor" href="#async-false-sync-the-default" aria-label="Permalink to “async: false (sync, the default)”">​</a></h2><p>The relationship is fully delivered with its parent.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;tags&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;collection&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;tag&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inverse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Whenever the relationship appears in a payload:</p><ul><li>its <code>data</code> member <strong>must</strong> be present (<code>null</code> or an identifier for a resource, an array for a collection). A links-only or meta-only payload is an error.</li><li>every referenced resource <strong>must</strong> be included.</li><li>it <strong>should not</strong> carry <code>links</code>. Links are never needed to load a sync relationship, so their presence usually means the field is misdeclared. The validator warns; the warning can be made an error with the <code>strict.syncRelationshipLinks</code> setting.</li></ul><p>With a sync relationship <code>doc.data</code> is always usable right away: the related record for a resource, an array of related records for a collection, or <code>null</code>/<code>[]</code> when empty.</p><p>Use sync relationships for data that is always needed together with its parent and is small enough to send with it.</p><h2 id="async-true" tabindex="-1"><code>async: true</code> <a class="header-anchor" href="#async-true" aria-label="Permalink to “async: true”">​</a></h2><p>The relationship is loaded on demand through a link.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;comments&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;collection&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;comment&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inverse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;post&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Every payload for the relationship <strong>must</strong> carry a <code>links</code> object with a <code>related</code> link. The validator reports a missing link as an error and the graph asserts on it in development builds. <code>data</code> may be omitted; until a payload with <code>data</code> arrives, <code>doc.data</code> is <code>undefined</code>:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">post.comments.data;          </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// undefined</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> post.comments.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// requests post.comments.links.related</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">post.comments.data;          </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// the comments the response returned</span></span></code></pre></div><p>If a payload does include <code>data</code>, the referenced resources must be included, exactly as for sync relationships.</p><p>WarpDrive does <strong>not</strong> fetch async relationships automatically: nothing is loaded until you call <code>fetch()</code>, which fills in <code>doc.data</code> and resolves with the relationship document. This differs from the legacy <code>belongsTo</code>/<code>hasMany</code> fields, which wrap async relationships in promise proxies that fetch on access.</p><p>Use async relationships when the related data is optional, expensive, or belongs to a different part of the UI than its parent.</p><h2 id="choosing" tabindex="-1">Choosing <a class="header-anchor" href="#choosing" aria-label="Permalink to “Choosing”">​</a></h2><table tabindex="0"><thead><tr><th>The API...</th><th>Declare</th></tr></thead><tbody><tr><td>always sends the members with the parent</td><td><code>async: false</code></td></tr><tr><td>sends a link and the members are loaded separately</td><td><code>async: true</code></td></tr><tr><td>sends a link <em>and</em> the members</td><td><code>async: true</code> (the link is required; the data is a bonus)</td></tr><tr><td>sends a large, pageable or filterable list</td><td>neither: model it as its own endpoint and load it with a <a href="./../advanced/large-collections">top-level request</a></td></tr></tbody></table>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};